import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BW2T23B9.js";const i="/docs/images/guide/fsrs-loop.svg",u=JSON.parse('{"title":"FSRS 复习","description":"FSRS（Free Spaced Repetition Scheduler）按你的记忆状态安排下一次复习。Turna 不会在固定天数后机械重现卡片，而是估计「现在还记得的概率」，在快要忘记时再拿出来。","frontmatter":{"description":"FSRS（Free Spaced Repetition Scheduler）按你的记忆状态安排下一次复习。Turna 不会在固定天数后机械重现卡片，而是估计「现在还记得的概率」，在快要忘记时再拿出来。"},"headers":[],"relativePath":"guide/fsrs.md","filePath":"guide/fsrs.md","lastUpdated":1787830168000}'),s={name:"guide/fsrs.md"};function o(l,t,n,h,c,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="fsrs-复习" tabindex="-1">FSRS 复习 <a class="header-anchor" href="#fsrs-复习" aria-label="Permalink to &quot;FSRS 复习&quot;">​</a></h1><p>FSRS（Free Spaced Repetition Scheduler）按你的记忆状态安排下一次复习。Turna 不会在固定天数后机械重现卡片，而是估计「现在还记得的概率」，在快要忘记时再拿出来。</p><p>产品页演示见 <a href="./../../fsrs.html">fsrs.html</a>。</p><h2 id="三个变量" tabindex="-1">三个变量 <a class="header-anchor" href="#三个变量" aria-label="Permalink to &quot;三个变量&quot;">​</a></h2><p>每张待复习的内容用三个数描述：</p><table tabindex="0"><thead><tr><th>符号</th><th>名称</th><th>含义</th></tr></thead><tbody><tr><td>D</td><td>难度 Difficulty</td><td>这张卡对你有多难，约 1–10。答得越好难度越低，连续答错则升高。</td></tr><tr><td>S</td><td>稳定度 Stability</td><td>记忆的半衰期尺度：经过 S 天后，留存率降到目标值（默认 90%）。</td></tr><tr><td>R</td><td>可提取性 Retrievability</td><td>此刻还能想起来的概率，随时间沿幂函数下降。</td></tr></tbody></table><p>复习时你给出「重来 / 困难 / 良好 / 简单」，FSRS 更新 D 和 S，并算出下一次间隔。</p><h2 id="两条引擎-同一套算法" tabindex="-1">两条引擎，同一套算法 <a class="header-anchor" href="#两条引擎-同一套算法" aria-label="Permalink to &quot;两条引擎，同一套算法&quot;">​</a></h2><p>Turna 里有两处 FSRS，参数语义一致，服务不同内容：</p><ul><li><strong>官方 Anki 牌组</strong>：走 Anki 内核里的 <code>fsrs-rs</code>，与桌面版 Anki 的调度一致。</li><li><strong>课程词、表达、语法</strong>：走应用内的 Dart <code>FsrsEngine</code>（FSRS-6，21 个参数）。</li></ul><p>课程练习的对错会映射到四个评分：判错 → 重来，打分 3 → 困难，判对或打分 4 → 良好，打分 ≥ 5 → 简单。</p><p><img src="'+i+'" alt="FSRS 评分 → 状态更新 → 再调度闭环与关键默认参数" loading="lazy"></p><h2 id="默认可调项" tabindex="-1">默认可调项 <a class="header-anchor" href="#默认可调项" aria-label="Permalink to &quot;默认可调项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th></tr></thead><tbody><tr><td>目标留存率</td><td>0.9（可在 0.8–0.95 间调整）</td></tr><tr><td>间隔上限</td><td>730 天</td></tr><tr><td>学习 / 重学短步进</td><td>10 分钟</td></tr><tr><td>同日容错</td><td>同一天最多 4 次失败</td></tr></tbody></table><p>完整参数分组（w0–w20）见产品页；日常使用不必改权重。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/anki">把已有 Anki 牌组导入 Turna</a></li><li><a href="/docs/guide/ai">按当前进度使用 AI 答疑</a></li></ul>',17)])])}const f=a(s,[["render",o]]);export{u as __pageData,f as default};
